use App\Support\DB;use App\Http\Controllers\Api\V1\ParcelDesignController as C;use App\Services\ParcelGeometry as G;
$n=0;function check($v,$msg){global $n;if(!$v)throw new RuntimeException($msg);$n++;echo "PASS $msg\n";}function deny(callable $f,$code){try{$f();throw new RuntimeException('Expected '.$code);}catch(Throwable $e){$v=json_decode($e->getMessage(),true);check(($v['code']??'')===$code,'Reject '.$code);}}
$admin=DB::selectOne("SELECT * FROM users WHERE role='admin' LIMIT 1");$citizen=DB::selectOne("SELECT * FROM users WHERE role='citizen' LIMIT 1");$maker=DB::selectOne("SELECT u.* FROM users u JOIN office_user ou ON ou.user_id=u.id JOIN offices o ON o.id=ou.office_id WHERE u.role='land_office_assistant' AND o.office_type='ac_land' AND o.is_active=1 LIMIT 1");
