$x=(float)$loc['longitude'];$y=(float)$loc['latitude'];$g=['type'=>'Polygon','coordinates'=>[[[$x,$y],[$x+.001,$y],[$x+.001,$y+.001],[$x,$y+.001],[$x,$y]]]];
