$bow=['type'=>'Polygon','coordinates'=>[[[$x,$y],[$x+.001,$y+.001],[$x+.001,$y],[$x,$y+.001],[$x,$y]]]];deny(fn()=>G::validate($bow),'SELF_INTERSECTION');deny(fn()=>G::validate(['type'=>'Polygon','coordinates'=>'wrong']),'SINGLE_POLYGON_REQUIRED');
