$asMaker=$checker;$asMaker['username']=$maker['username'];deny(fn()=>C::decide($id,['action'=>'publish','version'=>$r['version'],'reason'=>'QA maker checker separation test','review_confirmed'=>true],$asMaker),'INDEPENDENT_REVIEW_REQUIRED');
C::decide($id,['action'=>'return','version'=>$r['version'],'reason'=>'QA return for a source clarification'],$checker);$r=$get();check($r['status']==='RETURNED','Return for correction works');
C::save([...$b,'id'=>$id,'version'=>$r['version']],$maker);$r=$get();C::decide($id,['action'=>'submit','version'=>$r['version'],'reason'=>'QA revised source checked and resubmitted'],$maker);$r=$get();deny(fn()=>C::decide($id,['action'=>'publish','version'=>$r['version'],'reason'=>'QA missing map review confirmation'],$checker),'MAP_REVIEW_REQUIRED');C::decide($id,['action'=>'publish','version'=>$r['version'],'reason'=>'QA independent source and boundary review','review_confirmed'=>true],$checker);
$public=C::items(['location_id'=>$loc['id']],true)['items'];check(count($public)===1&&!isset($public[0]['created_by']),'Only published geometry is public');
