$revision=C::save([...$b,'supersedes_id'=>$id],$maker)['id'];$all=C::items(['location_id'=>$loc['id']],false,$maker)['items'];$rev=array_values(array_filter($all,fn($r)=>$r['id']===$revision))[0];C::decide($revision,['action'=>'submit','version'=>$rev['version'],'reason'=>'QA versioned correction submitted'],$maker);C::decide($revision,['action'=>'publish','version'=>$rev['version']+1,'reason'=>'QA replacement reviewed independently','review_confirmed'=>true],$checker);$pub=C::items(['location_id'=>$loc['id']],true)['items'];check(count($pub)===1&&$pub[0]['id']===$revision,'Revision replaces old public version');
